public class ShelfActivity extends Activity {
    final int RED=0xffdf3021,INK=0xff282828,GRAY=0xff999999;
    LinearLayout root, area, bottom;
    EditText search;
    TextView notice, commit, sort, manager, selectAll, removeSelected;
    AlertDialog removeDialog;
    final HashSet<String> selectedBooks=new HashSet<>();
    final ArrayList<Entry> files=new ArrayList<>();
    final ArrayList<Book> books=new ArrayList<>();
    boolean importing=false, busy=false, newest=true, manage=false, dead=false;
    String query="",uiLocale="";
    static class Entry {Uri uri;String name;long size,date;boolean selected;Entry(Uri u,String n,long s,long d){uri=u;name=n;size=s;date=d;}}
    static class Book {String id,name,source;long size,date;Book(String i,String n,String u,long s,long d){id=i;name=n;source=u;size=s;date=d;}}
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    TextView label(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView button(String s,LinearLayout p,int color){TextView t=label(s,16,color);t.setGravity(Gravity.CENTER);t.setMaxLines(2);t.setEllipsize(TextUtils.TruncateAt.END);t.setTextSize(14);t.setPadding(dp(8),dp(8),dp(8),dp(8));p.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));return t;}
    @Override public void onCreate(Bundle state){super.onCreate(state);loadBooks();shelf();}
    @Override protected void onResume(){super.onResume();if(root!=null&&!importing){loadBooks();renderShelf();}}
    void base(boolean red){uiLocale=AppLanguage.locale(this).toLanguageTag();root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff8f8f8);setContentView(root);getWindow().setStatusBarColor(red?RED:Color.WHITE);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR|View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();}
    void shelf(){importing=false;manage=false;selectedBooks.clear();query="";base(true);LinearLayout header=new LinearLayout(this);header.setOrientation(1);header.setPadding(dp(16),dp(12),dp(16),dp(16));header.setBackgroundColor(RED);root.addView(header);TextView brand=label(getString(R.string.ui_13),22,Color.WHITE);brand.setTypeface(null,Typeface.BOLD);header.addView(brand);search=new EditText(this);search.setSingleLine(true);search.setTextSize(15);search.setTextColor(Color.WHITE);search.setHintTextColor(0xffffd5cf);search.setHint(getString(R.string.ui_146));search.setPadding(dp(16),0,dp(16),0);search.setBackground(bg(0xffec6559,28));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(44));sp.topMargin=dp(12);header.addView(search,sp);search.addTextChangedListener(watcher(()->{query=search.getText().toString();renderShelf();}));
        LinearLayout caption=row();caption.setPadding(dp(18),dp(12),dp(18),dp(8));root.addView(caption);TextView heading=label(getString(R.string.ui_147),21,INK);heading.setTypeface(null,Typeface.BOLD);caption.addView(heading,new LinearLayout.LayoutParams(0,dp(44),1));manager=label(getString(R.string.ui_148),15,GRAY);manager.setPadding(dp(12),dp(10),dp(4),dp(10));manager.setContentDescription(getString(R.string.ui_149));caption.addView(manager);manager.setOnClickListener(v->setManage(!manage));
        ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));area=new LinearLayout(this);area.setOrientation(1);area.setPadding(dp(16),dp(8),dp(16),dp(24));scroll.addView(area);
        bottom=row();bottom.setBackgroundColor(Color.WHITE);root.addView(bottom);renderShelf();}
    void setManage(boolean value){manage=value;selectedBooks.clear();if(manager!=null)manager.setText(manage?getString(R.string.ui_150):getString(R.string.ui_148));renderShelf();}
    ArrayList<Book> visibleBooks(){ArrayList<Book> result=new ArrayList<>();for(Book b:books)if(b.name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))result.add(b);return result;}
    void toggleBook(Book book){if(!manage)return;if(!selectedBooks.add(book.id))selectedBooks.remove(book.id);renderShelf();}
    void renderShelfBottom(){bottom.removeAllViews();if(manage){selectAll=button(getString(R.string.ui_151),bottom,INK);selectAll.setContentDescription(getString(R.string.ui_152));ArrayList<Book> visible=visibleBooks();boolean all=!visible.isEmpty();for(Book b:visible)if(!selectedBooks.contains(b.id))all=false;selectAll.setText(all?getString(R.string.ui_153):query.isEmpty()?getString(R.string.ui_151):getString(R.string.ui_154));selectAll.setOnClickListener(v->{ArrayList<Book> current=visibleBooks();boolean selected=!current.isEmpty();for(Book b:current)if(!selectedBooks.contains(b.id))selected=false;for(Book b:current)if(selected)selectedBooks.remove(b.id);else selectedBooks.add(b.id);renderShelf();});removeSelected=button(getString(R.string.remove_count,selectedBooks.size()),bottom,Color.WHITE);removeSelected.setContentDescription(getString(R.string.ui_156));removeSelected.setBackgroundColor(RED);removeSelected.setEnabled(!selectedBooks.isEmpty());removeSelected.setAlpha(selectedBooks.isEmpty()?.45f:1f);removeSelected.setOnClickListener(v->confirmRemove());return;}TextView home=button(getString(R.string.ui_157),bottom,RED);TextView recent=button(getString(R.string.ui_158),bottom,GRAY);TextView more=button(getString(R.string.models_my),bottom,GRAY);home.setOnClickListener(v->{query="";search.setText("");});recent.setOnClickListener(v->{if(books.isEmpty())importPage();else open(books.get(0));});more.setOnClickListener(v->startActivity(new Intent(this,ModelManagerActivity.class).putExtra("home",true)));}
    void confirmRemove(){if(selectedBooks.isEmpty())return;final HashSet<String> pending=new HashSet<>(selectedBooks);removeDialog=new AlertDialog.Builder(this).setTitle(getString(R.string.remove_title,pending.size())).setMessage(getString(R.string.ui_162)).setNegativeButton(getString(R.string.ui_94),null).setPositiveButton(getString(R.string.ui_163),(d,w)->{int before=books.size();books.removeIf(book->pending.contains(book.id));selectedBooks.removeAll(pending);saveBooks();renderShelf();toast(getString(R.string.removed_count,before-books.size()));}).show();}
    void renderShelf(){if(importing||area==null)return;area.removeAllViews();HashSet<String> existing=new HashSet<>();for(Book b:books)existing.add(b.id);selectedBooks.retainAll(existing);renderShelfBottom();ArrayList<Book> filtered=visibleBooks();int offset=manage?0:1;int count=filtered.size()+offset;for(int start=0;start<count;start+=3){LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.TOP);area.addView(line);for(int col=0;col<3;col++){int index=start+col;LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);cell.setPadding(dp(7),dp(8),dp(7),dp(18));line.addView(cell,new LinearLayout.LayoutParams(0,-2,1));if(index>=count)continue;if(!manage&&index==0){TextView add=label("＋",54,GRAY);add.setGravity(Gravity.CENTER);GradientDrawable border=bg(Color.WHITE,5);border.setStroke(dp(1),0xffcccccc,dp(5),dp(4));add.setBackground(border);cell.addView(add,new LinearLayout.LayoutParams(-1,dp(138)));TextView caption=label(getString(R.string.ui_166),14,0xff666666);caption.setPadding(0,dp(8),0,0);cell.addView(caption);cell.setOnClickListener(v->importPage());continue;}Book b=filtered.get(index-offset);FrameLayout cover=new FrameLayout(this);cell.addView(cover,new LinearLayout.LayoutParams(-1,dp(138)));cover.setBackground(bg(0xfff1ecd9,2));TextView spine=new TextView(this);spine.setBackgroundColor(0xffded9c4);FrameLayout.LayoutParams edge=new FrameLayout.LayoutParams(dp(3),-1);edge.leftMargin=dp(5);cover.addView(spine,edge);TextView name=label(b.name,15,0xffaa9870);name.setGravity(Gravity.CENTER);name.setMaxLines(4);name.setPadding(dp(8),dp(24),dp(8),dp(24));cover.addView(name,new FrameLayout.LayoutParams(-1,-1));TextView txt=label("txt",12,Color.WHITE);txt.setGravity(Gravity.CENTER);txt.setBackground(bg(0xff1eb9ad,2));FrameLayout.LayoutParams badge=new FrameLayout.LayoutParams(dp(36),dp(25),Gravity.TOP|Gravity.END);badge.rightMargin=dp(10);cover.addView(txt,badge);int p=getSharedPreferences("reader_"+b.id,0).getInt("percent",0);TextView percent=label(getString(R.string.read_percent,p),12,Color.WHITE);percent.setGravity(Gravity.CENTER);percent.setBackgroundColor(0xbb282721);cover.addView(percent,new FrameLayout.LayoutParams(-1,dp(25),Gravity.BOTTOM));TextView caption=label(b.name,15,INK);caption.setPadding(0,dp(8),0,0);caption.setMaxLines(2);caption.setEllipsize(TextUtils.TruncateAt.END);cell.addView(caption);if(manage){boolean selected=selectedBooks.contains(b.id);TextView check=label(selected?"✓":"○",21,selected?Color.WHITE:GRAY);check.setGravity(Gravity.CENTER);check.setBackground(bg(selected?RED:0xffeeeeee,20));FrameLayout.LayoutParams mark=new FrameLayout.LayoutParams(dp(30),dp(30),Gravity.TOP|Gravity.START);mark.setMargins(dp(4),dp(4),0,0);cover.addView(check,mark);GradientDrawable border=bg(selected?0xffffede9:Color.TRANSPARENT,8);if(selected)border.setStroke(dp(1),RED);cell.setBackground(border);cell.setSelected(selected);cell.setContentDescription((selected?getString(R.string.ui_168):getString(R.string.ui_169))+b.name);}cell.setOnClickListener(v->{if(manage)toggleBook(b);else open(b);});cell.setOnLongClickListener(v->{if(!manage)setManage(true);toggleBook(b);return true;});}}}
    void open(Book b){books.remove(b);books.add(0,b);saveBooks();MainActivity reader=PlaybackService.reader();Intent open=new Intent(this,MainActivity.class).putExtra("book_id",b.id).putExtra("book_name",b.name);if(reader!=null){if(reader.bookFile.equals("book_"+b.id+".txt"))open.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP);else{reader.stop();reader.finish();}}startActivity(open);}
    void openCurrentReader(){MainActivity reader=PlaybackService.reader();if(reader!=null)startActivity(new Intent(reader.getIntent()).setClass(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));}
    void importPage(){importing=true;query="";base(false);LinearLayout top=row();top.setPadding(dp(12),dp(8),dp(12),dp(8));top.setBackgroundColor(Color.WHITE);root.addView(top);TextView back=label("‹",32,GRAY);top.addView(back,new LinearLayout.LayoutParams(dp(36),dp(48)));back.setOnClickListener(v->{if(!busy)shelf();});TextView pick=button(getString(R.string.ui_170),top,RED);TextView folder=button(getString(R.string.ui_171),top,RED);sort=button(newest?getString(R.string.ui_172):getString(R.string.ui_173),top,INK);pick.setOnClickListener(v->pickFiles());folder.setOnClickListener(v->pickFolder());sort.setOnClickListener(v->{newest=!newest;sort.setText(newest?getString(R.string.ui_172):getString(R.string.ui_173));renderFiles();});
        LinearLayout sr=row();sr.setPadding(dp(16),dp(8),dp(16),dp(8));sr.setBackgroundColor(Color.WHITE);root.addView(sr);search=new EditText(this);search.setSingleLine(true);search.setTextSize(15);search.setHint(getString(R.string.ui_174));search.setPadding(dp(14),0,dp(14),0);search.setBackground(bg(0xfff4f4f4,24));sr.addView(search,new LinearLayout.LayoutParams(-1,dp(42)));search.addTextChangedListener(watcher(()->{query=search.getText().toString();renderFiles();}));notice=label(getString(R.string.ui_175),12,GRAY);notice.setPadding(dp(16),dp(10),dp(16),dp(10));root.addView(notice);
        ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));area=new LinearLayout(this);area.setOrientation(1);area.setBackgroundColor(Color.WHITE);sc.addView(area);bottom=row();bottom.setBackgroundColor(Color.WHITE);root.addView(bottom);TextView all=button(getString(R.string.ui_151),bottom,INK);commit=button(getString(R.string.add_count,0),bottom,Color.WHITE);commit.setBackgroundColor(RED);all.setOnClickListener(v->{if(busy)return;boolean allSelected=true;for(Entry e:files)if(matches(e)&&!isImported(e)&&!e.selected)allSelected=false;for(Entry e:files)if(matches(e)&&!isImported(e))e.selected=!allSelected;renderFiles();});commit.setOnClickListener(v->importSelected());renderFiles();}
    TextWatcher watcher(Runnable r){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){r.run();}public void afterTextChanged(Editable e){}};}
    void pickFiles(){if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,11);}
    void pickFolder(){if(busy)return;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),12);}
    boolean matches(Entry e){return e.name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT));}
    boolean isImported(Entry e){for(Book b:books)if(b.source.equals(e.uri.toString()))return true;return false;}
    String size(long bytes){return bytes>=1048576?String.format(AppLanguage.locale(this),"%.2f MB",bytes/1048576f):bytes>=1024?String.format(AppLanguage.locale(this),"%.1f KB",bytes/1024f):bytes+" B";}
    void renderFiles(){if(!importing||area==null)return;area.removeAllViews();files.sort(newest?(a,b)->Long.compare(b.date,a.date):(a,b)->a.name.compareToIgnoreCase(b.name));int selected=0,visible=0;for(Entry e:files){if(e.selected&&!isImported(e))selected++;if(!matches(e))continue;visible++;LinearLayout line=row();line.setPadding(dp(16),dp(18),dp(16),dp(18));area.addView(line);TextView icon=label("TXT",13,Color.WHITE);icon.setGravity(Gravity.CENTER);icon.setBackground(bg(0xff08baab,4));line.addView(icon,new LinearLayout.LayoutParams(dp(34),dp(46)));LinearLayout info=new LinearLayout(this);info.setOrientation(1);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,-2,1);ip.leftMargin=dp(16);line.addView(info,ip);TextView name=label(e.name,18,INK);name.setMaxLines(2);info.addView(name);String date=e.date>0?java.text.DateFormat.getDateInstance(java.text.DateFormat.SHORT,AppLanguage.locale(this)).format(new Date(e.date)):"";TextView meta=label(size(e.size)+"  "+date,13,GRAY);meta.setPadding(0,dp(5),0,0);info.addView(meta);boolean imported=isImported(e);TextView check=label(imported?getString(R.string.ui_177):e.selected?"●":"○",imported?12:25,imported?GRAY:e.selected?RED:0xffcccccc);check.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);line.addView(check,new LinearLayout.LayoutParams(dp(60),dp(48)));line.setOnClickListener(v->{if(busy||isImported(e))return;e.selected=!e.selected;renderFiles();});View divider=new View(this);divider.setBackgroundColor(0xffeeeeee);area.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}commit.setText(busy?getString(R.string.ui_178):getString(R.string.add_count,selected));if(visible==0){TextView empty=label(files.isEmpty()?getString(R.string.ui_180):getString(R.string.ui_181),16,GRAY);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(24),dp(60),dp(24),dp(60));area.addView(empty);} }
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;if(req==11){ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int n=0;n<data.getClipData().getItemCount();n++)uris.add(data.getClipData().getItemAt(n).getUri());else if(data.getData()!=null)uris.add(data.getData());for(Uri uri:uris){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}try{Entry e=inspect(uri);if(e.name.toLowerCase(Locale.ROOT).endsWith(".txt"))addEntry(e);else toast(getString(R.string.ui_182)+e.name);}catch(Exception e){toast(getString(R.string.ui_183));}}renderFiles();notice.setText(getString(R.string.found_select,files.size()));}else if(req==12&&data.getData()!=null){Uri tree=data.getData();try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}busy=true;notice.setText(getString(R.string.ui_186));new Thread(()->{ArrayList<Entry> found=new ArrayList<>();String error=null;try{scan(tree,DocumentsContract.getTreeDocumentId(tree),found,0);}catch(Exception e){error=getString(R.string.ui_187);}final String msg=error;runOnUiThread(()->{if(dead)return;busy=false;for(Entry e:found)addEntry(e);notice.setText(msg!=null?msg:getString(R.string.found_files,files.size()));renderFiles();});}).start();}}
    Entry inspect(Uri uri){String name=getString(R.string.ui_189);long bytes=0,date=0;try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME),s=c.getColumnIndex(OpenableColumns.SIZE),d=c.getColumnIndex(DocumentsContract.Document.COLUMN_LAST_MODIFIED);if(n>=0)name=c.getString(n);if(s>=0)bytes=c.getLong(s);if(d>=0)date=c.getLong(d);}}return new Entry(uri,name,bytes,date);}
    void addEntry(Entry e){for(Entry old:files)if(old.uri.equals(e.uri))return;files.add(e);}
    void scan(Uri tree,String id,ArrayList<Entry> found,int depth)throws Exception{if(depth>20||found.size()>=3000)return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED},null,null,null)){if(c==null)return;while(c.moveToNext()){if(dead||found.size()>=3000)return;String child=c.getString(0),name=c.getString(1),mime=c.getString(2);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime))scan(tree,child,found,depth+1);else if(name!=null&&name.toLowerCase(Locale.ROOT).endsWith(".txt"))found.add(new Entry(DocumentsContract.buildDocumentUriUsingTree(tree,child),name,c.getLong(3),c.getLong(4)));}}}
    void importSelected(){if(busy)return;ArrayList<Entry> selected=new ArrayList<>();for(Entry e:files)if(e.selected&&!isImported(e))selected.add(e);if(selected.isEmpty()){toast(getString(R.string.ui_190));return;}busy=true;renderFiles();notice.setText(getString(R.string.ui_191));new Thread(()->{ArrayList<Book> added=new ArrayList<>();int failed=0;for(Entry e:selected){try{String text;try(InputStream in=getContentResolver().openInputStream(e.uri)){text=MainActivity.decode(MainActivity.readBytes(in)).replace("\uFEFF","").replace("\r\n","\n").replace('\r','\n').replace("\u0000","");}if(text.trim().isEmpty())throw new IOException();String id=UUID.randomUUID().toString();try(FileOutputStream out=openFileOutput("book_"+id+".txt",MODE_PRIVATE)){out.write(text.getBytes(StandardCharsets.UTF_8));}added.add(new Book(id,e.name.replaceFirst("(?i)\\.txt$",""),e.uri.toString(),e.size,System.currentTimeMillis()));}catch(Exception ex){failed++;}}final int failures=failed;runOnUiThread(()->{busy=false;books.addAll(0,added);saveBooks();if(dead)return;for(Entry e:selected)e.selected=false;if(added.isEmpty()){notice.setText(getString(R.string.ui_192));renderFiles();}else{toast(getString(R.string.added_result,added.size(),failures));shelf();}});}).start();}
    void loadBooks(){books.clear();try{JSONArray arr=new JSONArray(getSharedPreferences("shelf",0).getString("books","[]"));for(int i=0;i<arr.length();i++){JSONObject o=arr.getJSONObject(i);books.add(new Book(o.getString("id"),o.getString("name"),o.optString("source"),o.optLong("size"),o.optLong("date")));}}catch(Exception ignored){}}
    void saveBooks(){JSONArray arr=new JSONArray();try{for(Book b:books){JSONObject o=new JSONObject();o.put("id",b.id);o.put("name",b.name);o.put("source",b.source);o.put("size",b.size);o.put("date",b.date);arr.put(o);}getSharedPreferences("shelf",0).edit().putString("books",arr.toString()).apply();}catch(Exception ignored){}}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override public void onBackPressed(){if(manage&&!importing)setManage(false);else if(importing&&!busy)shelf();else if(!busy){if(PlaybackService.reader()!=null)moveTaskToBack(true);else super.onBackPressed();}else toast(getString(R.string.ui_196));}
    @Override public void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);if(uiLocale.equals(AppLanguage.locale(this).toLanguageTag()))return;boolean wasImporting=importing,wasManage=manage;String previousQuery=query;HashSet<String> selected=new HashSet<>(selectedBooks);if(removeDialog!=null)removeDialog.dismiss();if(wasImporting){importPage();if(busy)notice.setText(getString(R.string.ui_196));}else{shelf();manage=wasManage;selectedBooks.addAll(selected);manager.setText(getString(manage?R.string.ui_150:R.string.ui_148));}search.setText(previousQuery);if(wasImporting)renderFiles();else renderShelf();}
    @Override protected void onDestroy(){dead=true;if(removeDialog!=null)removeDialog.dismiss();super.onDestroy();}
}
